<?php
session_start();if(($_SESSION['role']??'')!=='admin'){header('Location: /authenication/login/login.php');exit;}require_once(__DIR__.'/../../../Database/db/db.php');$pdo=get_db();$start=$_GET['start']??date('Y-m-01');$end=$_GET['end']??date('Y-m-d');foreach(['start','end'] as $key){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',${$key})){${$key}=$key==='start'?date('Y-m-01'):date('Y-m-d');}}$courseId=filter_var($_GET['course_id']??'',FILTER_VALIDATE_INT);$courses=$pdo->query('SELECT id,title FROM courses ORDER BY title')->fetchAll(PDO::FETCH_ASSOC);$where='DATE(e.created_at) BETWEEN ? AND ?';$params=[$start,$end];if($courseId){$where.=' AND e.course_id=?';$params[]=$courseId;}$q=$pdo->prepare("SELECT COUNT(*) total,COUNT(DISTINCT e.user_id) learners,SUM(e.status='completed') completed FROM enrollments e WHERE $where");$q->execute($params);$stats=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT DATE(e.created_at) day,COUNT(*) enrollments FROM enrollments e WHERE $where GROUP BY DATE(e.created_at) ORDER BY day DESC LIMIT 31");$q->execute($params);$daily=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT u.full_name,u.username,c.title course_title,e.status,e.progress,e.created_at FROM enrollments e JOIN users u ON u.id=e.user_id JOIN courses c ON c.id=e.course_id WHERE $where ORDER BY e.created_at DESC LIMIT 100");$q->execute($params);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Enrollment reports';include(__DIR__.'/../../includes/header/header.php');include(__DIR__.'/../../includes/navbar/navbar.php');include(__DIR__.'/../../includes/sidebar/sidebar.php');
?>
<main class="main-content"><div class="container-fluid"><div class="page-heading"><div><span class="page-kicker">REPORTS</span><h1>Enrollment reports</h1><p>Explore enrollment activity by date range and course.</p></div></div><section class="card border-0 mb-4"><div class="card-body"><form class="row g-3 align-items-end" method="get"><div class="col-sm-3"><label class="form-label">From</label><input class="form-control" type="date" name="start" value="<?=htmlspecialchars($start)?>"></div><div class="col-sm-3"><label class="form-label">Through</label><input class="form-control" type="date" name="end" value="<?=htmlspecialchars($end)?>"></div><div class="col-sm-4"><label class="form-label">Course</label><select class="form-select" name="course_id"><option value="">All courses</option><?php foreach($courses as $course):?><option value="<?=(int)$course['id']?>" <?=(int)$courseId===(int)$course['id']?'selected':''?>><?=htmlspecialchars($course['title'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></div><div class="col-sm-2"><button class="btn btn-primary">Apply</button></div></form></div></section><div class="row g-3 mb-4"><div class="col-sm-4"><div class="metric-card"><span class="metric-icon purple"><i class="fa-solid fa-address-card"></i></span><span class="metric-label">Enrollments</span><strong><?=number_format((int)$stats['total'])?></strong><small>Selected period</small></div></div><div class="col-sm-4"><div class="metric-card"><span class="metric-icon blue"><i class="fa-solid fa-users"></i></span><span class="metric-label">Learners</span><strong><?=number_format((int)$stats['learners'])?></strong><small>Distinct students</small></div></div><div class="col-sm-4"><div class="metric-card"><span class="metric-icon green"><i class="fa-solid fa-circle-check"></i></span><span class="metric-label">Completed</span><strong><?=number_format((int)$stats['completed'])?></strong><small>Enrollment records</small></div></div></div><div class="row g-4"><div class="col-xl-4"><section class="card border-0 h-100"><div class="table-toolbar"><h2 class="h5 mb-0">Daily activity</h2></div><div class="table-responsive"><table class="table admin-table mb-0"><thead><tr><th>Date</th><th>Count</th></tr></thead><tbody><?php if(!$daily):?><tr><td colspan="2" class="text-center text-muted">No activity</td></tr><?php endif;?><?php foreach($daily as $day):?><tr><td><?=htmlspecialchars(date('M j, Y',strtotime($day['day'])))?></td><td><?=number_format((int)$day['enrollments'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><div class="col-xl-8"><section class="card border-0"><div class="table-toolbar"><div><h2 class="h5 mb-1">Enrollment records</h2><small class="text-muted">Showing up to 100 recent records</small></div><div class="table-search"><i class="fa-solid fa-magnifying-glass"></i><input data-table-search="enrollmentTable" placeholder="Search records" aria-label="Search enrollments"></div></div><div class="table-responsive"><table class="table admin-table mb-0" id="enrollmentTable" data-admin-sort><thead><tr><th data-sort>Student</th><th data-sort>Course</th><th data-sort>Status</th><th data-sort>Progress</th><th data-sort>Enrolled</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-4">No enrollment records found.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['full_name']?:$row['username'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['course_title'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(ucfirst($row['status']),ENT_QUOTES,'UTF-8')?></td><td><?=number_format((float)$row['progress'],1)?>%</td><td><?=htmlspecialchars(date('M j, Y',strtotime($row['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section></div></div></div></main><?php include(__DIR__.'/../../includes/footer/footer.php');?>
